CREATE OR REPLACE FUNCTION public.validate_family_checkin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.patients%ROWTYPE; item jsonb; original text; cat text; BEGIN SELECT * INTO p FROM public.patients WHERE id=NEW.patient_id FOR SHARE; IF p.ai_plan IS NULL OR (p.cognitive_risk IN ('中风险','高风险') AND (p.ai_plan_confirmed_at IS NULL OR p.ai_plan_confirmed_at<p.ai_plan_at)) THEN RAISE EXCEPTION '请等待医生确认方案'; END IF; IF (p.ai_plan_at IS NULL AND NEW.plan_version<>'initial') OR (p.ai_plan_at IS NOT NULL AND NEW.plan_version::timestamptz IS DISTINCT FROM p.ai_plan_at) THEN RAISE EXCEPTION '方案已更新，请重新打开任务'; END IF;
IF NEW.task_key ~ '^training-[0-9]+$' THEN item=p.ai_plan->'training'->(split_part(NEW.task_key,'-',2)::integer); IF item IS NULL OR NEW.category<>'训练' OR coalesce(item->>'setting','') NOT IN ('家庭作业','家庭任务','居家','家庭') OR NEW.title IS DISTINCT FROM item->>'activity' THEN RAISE EXCEPTION '训练任务必须来自已确认的家庭方案'; END IF;
ELSIF NEW.task_key ~ '^intervention-[0-9]+-[0-9]+$' THEN item=p.ai_plan->'interventions'->(split_part(NEW.task_key,'-',2)::integer); IF item IS NULL OR coalesce(item->>'category','') NOT IN ('营养','睡眠') OR NEW.category IS DISTINCT FROM item->>'category' OR NEW.title IS DISTINCT FROM (item->'actions'->>(split_part(NEW.task_key,'-',3)::integer)) THEN RAISE EXCEPTION '任务必须来自营养或睡眠方案'; END IF;
ELSIF NEW.task_key ~ '^(followup|caregiver)-[0-9]+$' AND coalesce(jsonb_array_length(p.ai_plan->'interventions'),0)=0 THEN IF NEW.task_key LIKE 'followup-%' THEN original=p.ai_plan->'followup'->'items'->>(split_part(NEW.task_key,'-',2)::integer); ELSE original=p.ai_plan->'caregiver_tips'->>(split_part(NEW.task_key,'-',2)::integer); END IF; cat=CASE WHEN original ~ '家庭作业' THEN '训练' WHEN original ~ '睡眠|作息' THEN '睡眠' WHEN original ~ '营养|饮食|食欲' THEN '营养' END; IF original IS NULL OR original ~ '用药|服药|降压药|助眠药' OR cat IS NULL OR NEW.category IS DISTINCT FROM cat OR NEW.title IS DISTINCT FROM original THEN RAISE EXCEPTION '任务必须来自原方案家庭建议'; END IF;
ELSE RAISE EXCEPTION '任务不存在'; END IF; RETURN NEW; END $$;